1645      private void genParallelExprs(List<? extends Expr> args, Type domain_type, List<VarCodeGen> vcgs, boolean clearStackAtEnd) {
1646          final int n = args.size();
1647          if (n <= 0) return;
1648          
1649          List<Type> domain_types;
1650          if (NodeUtil.isVoidType(domain_type)) {
1651              domain_types = new ArrayList<Type>();
1652              for (int i = 0; i < n; i++)
1653                  domain_types.add(domain_type);
1654          } else if (args.size() != 1 && domain_type instanceof TupleType) {
1655              TupleType tdt = (TupleType) domain_type;
1656              domain_types = tdt.getElements();
1657          } else {
1658              domain_types = Collections.singletonList(domain_type);
1659          }
1660          
1661          String [] tasks = new String[n];
1662          String [] results = new String[n];
1663          int [] taskVars = new int[n];
1664  
1665          if (vcgs != null && vcgs.size() != n) {
1666              System.out.println("vcgs size = " + vcgs.size() + " n = " + n);
1667              throw sayWhat(args.get(0), "Internal error: number of args does not match number of consumers.");
1668          }
1669  
1670          // Push arg tasks from right to left, so
1671          // that local evaluation of args will proceed left to right.
1672          // IMPORTANT: ALWAYS fork and join stack fashion,
1673          // ie always join with the most recent fork first.
1674          for (int i = n-1; i > 0; i--) {
1675              Expr arg = args.get(i);
1676              // Make sure arg has type info (we'll need it to generate task)
1677              Option<Type> ot = NodeUtil.getExprType(arg);
1678              if (!ot.isSome())
1679                  throw sayWhat(arg, "Missing type information for argument " + arg);
1680              Type t = ot.unwrap();
1681              String tDesc = NamingCzar.jvmBoxedTypeDesc(t, component.getName());
1682              // Find free vars of arg
1683              List<VarCodeGen> freeVars = getFreeVars(arg);
1684              BASet<VarType> fvts = fvt.freeVarTypes(arg);
1685  
1686              // Generate descriptor for init method of task
1687              String init = taskConstructorDesc(freeVars);
1688  
1689              String task = delegate(arg, tDesc, init, freeVars, fvts);
1690              tasks[i] = task;
1691              results[i] = tDesc;
1692              constructWithFreeVars(task, freeVars, init);
1693  
1694              mv.visitInsn(DUP);
1695              int taskVar = mv.createCompilerLocal(task, // Naming.mangleIdentifier(task),
1696                                                   Naming.internalToDesc(task));
1697              taskVars[i] = taskVar;
1698              mv.visitVarInsn(ASTORE, taskVar);
1699              mv.visitMethodInsn(INVOKEVIRTUAL, task, "forkIfProfitable", "()V");
1700          }
1701  
1702          // arg 0 gets compiled in place, rather than turned into work.
1703          args.get(0).accept(this);
1704          conditionallyCastParameter(args.get(0), domain_types.get(0));
1705          if (vcgs != null) vcgs.get(0).assignValue(mv);
1706          if (clearStackAtEnd) popAll(mv, 0); 
1707  
1708          // join / perform work locally left to right, leaving results on stack.
1709          for (int i = 1; i < n; i++) {
1710              int taskVar = taskVars[i];
1711              mv.visitVarInsn(ALOAD, taskVar);
1712              mv.disposeCompilerLocal(taskVar);
1713              mv.visitInsn(DUP);
1714              String task = tasks[i];
1715              mv.visitMethodInsn(INVOKEVIRTUAL, task, "joinOrRun", "()V");
1716              mv.visitFieldInsn(GETFIELD, task, "result", results[i]);
1717              conditionallyCastParameter(args.get(i), domain_types.get(i));
1718              if (vcgs != null) vcgs.get(i).assignValue(mv);
1719              if (clearStackAtEnd) popAll(mv, 1);  // URGH!!!  look into better stack management...            
1720          }
1721      }

