    private final HashSet<ASTNode> worthy = new HashSet<ASTNode>();
    private final HashSet<ASTNode> computeIntensive = new HashSet<ASTNode>();

    private void addToWorthy(ASTNode x) {
        if (ANALYZATION_ON) { 
