    }

    private void addToComputeIntensive(ASTNode x) {
        if (ANALYZATION_ON) {
            debug(x, "adding to computeIntensive");
            computeIntensive.add(x);
        }
    }

    private void removeFromComputeIntensive(ASTNode x) {
        if (ANALYZATION_ON) {
            debug(x, "removing from computeIntensive");
