    public boolean worthParallelizing(ASTNode n) {
        if (ANALYZATION_ON) {
            if (worthy.contains(n)) {
                debug(n, "worthy of parallizing");
                return true;
            } else {
                debug(n, "not worthy of parallizing");
                return false;
            }
        }
        return false;
