                domain_types = tdt.getElements();
            } else {
                domain_types = Collections.singletonList(domain_type);
            }
            int i = 0;
            for (Expr arg : args) {
                arg.accept(this);
                conditionallyCastParameter(arg, domain_types.get(i));
                i++;
            }

